import { Type } from 'class-transformer';
import {
  IsEnum,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  MinLength,
} from 'class-validator';
import { MessageType } from '../../../generated/prisma/client';

export class WsSendMessagePayload {
  @IsUUID('4')
  conversationId: string;

  @IsString()
  @MinLength(1)
  @MaxLength(4000)
  body: string;

  @IsOptional()
  @IsEnum(MessageType)
  type?: MessageType;

  /** Idempotency key generated by the client. */
  @IsOptional()
  @IsString()
  @MaxLength(64)
  clientId?: string;

  @IsOptional()
  @IsUUID('4')
  replyToId?: string;
}

export class WsConversationPayload {
  @IsUUID('4')
  conversationId: string;
}

export class WsTypingPayload extends WsConversationPayload {
  /** When false the client is no longer typing. */
  @IsOptional()
  typing?: boolean;
}

export class WsReadPayload extends WsConversationPayload {
  @IsOptional()
  @IsUUID('4', { each: true })
  messageIds?: string[];
}

export class WsMessagePayload {
  @IsUUID('4')
  messageId: string;
}

export class WsEditMessagePayload extends WsMessagePayload {
  @Type(() => String)
  @IsString()
  @MinLength(1)
  @MaxLength(4000)
  body: string;
}
